"use strict";

// Shared WYSIWYG registry helpers for non-bundled CJS consumers (the drift
// guard / corpus gate, the safe-set generator, and the baseline runner).
//
// The set of files whose Milkdown body round-trip is proven safe is NO LONGER a
// hand-curated allowlist in domains.json. It is CI-generated by walking every
// editable file and actually round-tripping it (editor/scripts/gen-wysiwyg-safe-paths.ts
// → editor/src/generated/wysiwyg-safe-paths.json). These helpers supply the two
// pure (DOM-free) pieces that generation and the corpus gate share:
//   - editableSourceFiles(repoRoot): the walked universe (no existsSync skips).
//   - distEquivalenceForPath(domainsJson, relPath): the per-file dist-equivalence
//     config, resolved by the path's DOMAIN (src glob), not by allowlist membership.

const fs = require("node:fs");
const path = require("node:path");

// Basenames that are structural/docs or frontmatter-data records, never a WYSIWYG
// prose body. AUTHORING/README/EDITING-GUIDE are authoring docs; words-to-avoid.md
// is a frontmatter-data record (its content is the `wordsToAvoid` YAML edited via a
// form, the markdown body is a stub), so it is not a body candidate; kept out
// deliberately (the wysiwygPaths gate test pins it OUT of the safe set).
const EXCLUDED_BODY_BASENAMES = new Set([
  "AUTHORING.md",
  "README.md",
  "EDITING-GUIDE.md",
  "words-to-avoid.md",
]);

// The four per-component guideline body kinds (the guidelines domain src glob:
// components/src/*/{content,usage,design,behavior}.md).
const GUIDELINE_BODY_BASENAMES = ["content", "usage", "design", "behavior"];

// Literal prefix of a src glob (up to the first `*` or `{`), trailing slash
// trimmed. Same idea as scripts/validate/validate-domains.js#globPrefix; inlined
// here to avoid pulling that module's ajv dependency into pure consumers.
function globPrefix(glob) {
  const i = glob.search(/[*{]/);
  const lit = i === -1 ? glob : glob.slice(0, i);
  return lit.replace(/\/+$/, "");
}

/**
 * Look up the distEquivalence config for a repo-relative source path by matching
 * it against each domain's `src` glob prefix (NOT by allowlist membership).
 * Returns the matching domain's `wysiwyg.distEquivalence`, or null when the
 * domain declares none (e.g. content/*, whose dist-safety is proven holistically
 * by a CI derive-and-diff gate rather than per-file in the guard).
 *
 * @param {object} domainsJson - Parsed domains.json object.
 * @param {string} relPath - Repo-relative source path, e.g. "foundations/src/intro.md".
 * @returns {{ engine: string, sourceRel?: string, rootAnchor?: string, applySkipH2Slugs?: boolean } | null}
 */
function distEquivalenceForPath(domainsJson, relPath) {
  for (const domain of Object.values(domainsJson.domains)) {
    if (!domain.src) continue;
    const prefix = globPrefix(domain.src);
    if (relPath === prefix || relPath.startsWith(prefix + "/")) {
      return domain.wysiwyg?.distEquivalence ?? null;
    }
  }
  return null;
}

// Repo-relative, forward-slash normalization of an absolute path.
function relPosix(repoRoot, abs) {
  return path.relative(repoRoot, abs).split(path.sep).join("/");
}

// Collect .md files under absDir (optionally recursive), skipping the excluded
// structural/data basenames. Missing directories yield [] (not an error).
function listMarkdown(absDir, recursive) {
  const out = [];
  let entries;
  try {
    entries = fs.readdirSync(absDir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const abs = path.join(absDir, entry.name);
    if (entry.isDirectory()) {
      if (recursive) out.push(...listMarkdown(abs, recursive));
    } else if (
      entry.isFile() &&
      entry.name.endsWith(".md") &&
      !EXCLUDED_BODY_BASENAMES.has(entry.name)
    ) {
      out.push(abs);
    }
  }
  return out;
}

/**
 * Walk every editable markdown BODY the WYSIWYG editor can open, across the body
 * domains (foundations, accessibility, content, and per-component guidelines).
 * Returns sorted, unique, repo-relative forward-slash paths. Excludes the
 * structural/data basenames (see EXCLUDED_BODY_BASENAMES).
 *
 * This is the walked universe for the safe-set generator AND the corpus gate:
 * one source of truth, so neither can silently skip a file the other checks.
 *
 * Content is walked recursively (content/src root files like global-guidelines.md
 * and the writing/product/patterns subdirs both matter), which is why this is a
 * purpose-built walk rather than a literal expansion of the domain src globs.
 *
 * @param {string} repoRoot - Absolute path to the repository root.
 * @returns {string[]}
 */
function editableSourceFiles(repoRoot) {
  const files = [];
  // Flat prose domains.
  for (const dir of ["foundations/src", "accessibility/src"]) {
    files.push(...listMarkdown(path.join(repoRoot, dir), false));
  }
  // Content: root-level files + writing/product/patterns subdirs.
  files.push(...listMarkdown(path.join(repoRoot, "content/src"), true));
  // Per-component guideline bodies (only the four declared body kinds).
  const componentsRoot = path.join(repoRoot, "components", "src");
  let slugEntries;
  try {
    slugEntries = fs.readdirSync(componentsRoot, { withFileTypes: true });
  } catch {
    slugEntries = [];
  }
  for (const slug of slugEntries) {
    if (!slug.isDirectory()) continue;
    for (const base of GUIDELINE_BODY_BASENAMES) {
      const abs = path.join(componentsRoot, slug.name, base + ".md");
      if (fs.existsSync(abs)) files.push(abs);
    }
  }
  return [...new Set(files.map((abs) => relPosix(repoRoot, abs)))].sort();
}

/**
 * Compute the comparable dist-equivalence "view" of a source body, dispatching
 * on the engine declared in its domain's distEquivalence config. The drift guard
 * compares this view before/after a Milkdown round-trip; equality proves the
 * round-trip is dist-safe for that file.
 *
 * Returns null when the path's domain declares no distEquivalence; those domains
 * (content/*) prove dist-safety holistically via a CI derive-and-diff gate
 * instead of per-file in the guard.
 *
 * Derive engines are LAZY-required so pure consumers that only need the walk /
 * lookup don't pay to load them:
 *   - "section-dist"       foundations/accessibility: parse into a Pattern-H
 *                          file tree via deriveFromMarkdown(); returns `.files`.
 *   - "guideline-sections" per-component guidelines: parse into the structured
 *                          sections[] array via guideline-md-parser; returns
 *                          `.sections`. The verbatim `markdown` field is
 *                          intentionally NOT part of the view: it drifts
 *                          rendered-equivalent across the round-trip (bullets,
 *                          HR, escapes, IAL removal) and is locked instead by
 *                          the full-dist no-op gate.
 *
 * @param {object} domainsJson - Parsed domains.json object.
 * @param {string} relPath - Repo-relative source path, e.g. "components/src/button/content.md".
 * @param {string} body - Markdown body with frontmatter already stripped.
 * @returns {unknown | null}
 */
function deriveEquivalenceView(domainsJson, relPath, body) {
  const cfg = distEquivalenceForPath(domainsJson, relPath);
  if (cfg === null) return null;
  if (cfg.engine === "section-dist") {
    const { deriveFromMarkdown } = require("./section-dist/index.js");
    const { SKIP_H2_SLUGS } = require("../foundations/derive-foundations.js");
    return deriveFromMarkdown(body, {
      sourceRel: cfg.sourceRel,
      ...(cfg.rootAnchor !== undefined ? { rootAnchor: cfg.rootAnchor } : {}),
      ...(cfg.applySkipH2Slugs ? { skipH2Slugs: SKIP_H2_SLUGS } : {}),
      logger: { warn: () => {} },
    }).files;
  }
  if (cfg.engine === "guideline-sections") {
    const {
      parseGuidelineMarkdown,
    } = require("../components/guideline-md-parser.js");
    return parseGuidelineMarkdown(body).sections;
  }
  throw new Error(
    `wysiwyg-registry: unknown distEquivalence engine "${cfg.engine}" for ${relPath}`,
  );
}

module.exports = {
  distEquivalenceForPath,
  editableSourceFiles,
  deriveEquivalenceView,
};
